module four_corner_mounting_holes() {
  union() {
    translate([hole_pitch/2, hole_pitch/2, 0]) mount_hole_cyl();
    translate([-hole_pitch/2, hole_pitch/2, 0]) mount_hole_cyl();
    translate([-hole_pitch/2, -hole_pitch/2, 0]) mount_hole_cyl();
    translate([hole_pitch/2, -hole_pitch/2, 0]) mount_hole_cyl();
  }
}

