        translate([-len/2 + r, 0, 0]) cylinder(d=2*r, h=h, center=false);
        translate([ len/2 - r, 0, 0]) cylinder(d=2*r, h=h, center=false);
    }
    // widen to w using intersection with a box
    intersection() {
        translate([0,0,h/2]) cube([len, w, h], center=true);
        hull() {
            translate([-len/2 + r, 0, 0]) cylinder(d=2*r, h=h, center=false);
            translate([ len/2 - r, 0, 0]) cylinder(d=2*r, h=h, center=false);
        }
    }
