                        translate([-arm_len/2 + arm_tip_r, 0, 0]) cylinder(r=arm_tip_r, h=arm_th, center=false);
                        translate([ arm_len/2 - arm_tip_r, 0, 0]) cylinder(r=arm_tip_r, h=arm_th, center=false);
